package org.marketreview.nativeapp;
import java.io.*;
import java.util.*;
import org.json.*;
final class FuturesMonitorChecks {
 static final String NOW="2026-10-13T02:02:10Z";
 static final String PAYLOAD="var _IF0=([{\"d\":\"2026-10-13 10:01:00\",\"o\":\"4000\",\"c\":\"4001\",\"v\":\"0\",\"p\":\"100\"},{\"d\":\"2026-10-13 10:02:00\",\"c\":\"4003\",\"v\":\"5\",\"p\":\"103\"}]);";
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static JSONObject model()throws Exception{
  JSONObject r=FuturesMonitorModel.parse("IF0",PAYLOAD,NOW),s=r.getJSONObject("summary");check("available".equals(r.getString("availability"))&&s.getDouble("minutePriceChange")==2&&s.getDouble("openInterestChange")==3,"actual JSONP adjacent deltas");check(r.getString("instrumentId").equals("CFFEX:continuous:IF0")&&r.isNull("expiry")&&r.isNull("exchangeTradingDay"),"separate continuous identity");check(r.getJSONArray("rows").getJSONObject(0).getDouble("volume")==0,"zero kept");check(FuturesMonitorModel.parse("IF0",PAYLOAD.replace("10:01:00","10:00:00"),NOW).getJSONObject("summary").isNull("minutePriceChange"),"gap delta null");check(FuturesMonitorModel.parse("IF0",PAYLOAD,"2026-10-13T10:01:30+08:00").getJSONArray("rows").length()==1,"future excluded");check(FuturesMonitorModel.parse("IF0","bad",NOW).getString("availability").equals("unavailable"),"bad response unavailable");check(FuturesMonitorModel.parse("IF0","x=([{\"d\":\"2026-10-13 10:02:00\",\"c\":1,\"v\":1}]);",NOW).getString("availability").equals("unavailable"),"missing oi not zero");check(FuturesMonitorModel.parse("IF0",PAYLOAD.replace("_IF0","_IH0"),NOW).getString("availability").equals("unavailable"),"declared identity mismatch");check(FuturesMonitorModel.parse("IF0",PAYLOAD.replace("2026-10-13","2026-02-30"),NOW).getString("availability").equals("unavailable"),"strict date");check(FuturesMonitorModel.parse("IF0",PAYLOAD.replace("10:01:00","00:01:00").replace("10:02:00","00:02:00"),NOW).isNull("exchangeTradingDay"),"night no trading-day guess");boolean failed=false;try{FuturesMonitorModel.parse("IF2410",PAYLOAD,NOW);}catch(Exception e){failed=true;}check(failed,"no guessed expiry");FuturesMonitorModel.validate(r);JSONObject tamper=new JSONObject(r.toString()).put("summary",new JSONObject());failed=false;try{FuturesMonitorModel.validate(tamper);}catch(Exception e){failed=true;}check(failed,"tamper rejected");return r;
 }
 public static void main(String[] args)throws Exception{model();if(args.length>0){JSONObject golden=new JSONObject(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(args[0])),java.nio.charset.StandardCharsets.UTF_8));JSONArray a=golden.getJSONArray("cases");for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i),r=FuturesMonitorModel.parse(c.getString("symbol"),c.getString("payload"),c.getString("receivedAt")),s=r.getJSONObject("summary"),e=c.getJSONObject("expected");for(String key:Arrays.asList("price","minuteVolume","openInterest","minutePriceChange","openInterestChange","sessionChangePct")){check(Math.abs(s.getDouble(key)-e.getDouble(key))<.00001,"actual old JS "+key);}check(s.getString("positioningState").equals(e.getString("positioningState")),"actual old state");}}System.out.println("PASS FuturesMonitor Java actual JSONP/old source fields/null/gaps/future/continuous identity/tamper; fixture-only");}
 static void run(FlowInstrumentation f)throws Exception{
  JSONObject record=model();File file=new File(f.activity.getCacheDir(),"futures-monitor-"+UUID.randomUUID()+".sqlite");FuturesMonitorStore store=new FuturesMonitorStore(file);store.save(record);store.save(record);check(store.history("IF0",0,20).length()==1,"append idempotent");check(FuturesMonitorModel.canonical(store.read(record.getString("id"))).equals(FuturesMonitorModel.canonical(record)),"stored exact source");boolean failed=false;try{store.save(FuturesMonitorModel.parse("IF0","bad",NOW));}catch(Exception e){failed=true;}check(failed&&store.history("IF0",0,20).length()==1,"failed save preserves history");
  StringBuilder padding=new StringBuilder();for(int i=0;i<300000;i++)padding.append('x');String large=PAYLOAD.replace("\"o\":\"4000\"","\"o\":\"4000\",\"uninterpreted\":\""+padding+"\"");JSONObject largeRecord=FuturesMonitorModel.parse("IM0",large.replace("_IF0","_IM0"),NOW);store.save(largeRecord);check(store.read(largeRecord.getString("id")).getString("rawPayload").equals(large.replace("_IF0","_IM0")),"large complete BLOB chunk read");for(int i=0;i<24;i++){String t=java.time.Instant.parse(NOW).plusSeconds(i+1).toString();store.save(FuturesMonitorModel.parse("IH0",PAYLOAD.replace("_IF0","_IH0"),t));}check(store.history("IH0",0,20).length()==20&&store.history("IH0",20,20).length()==4,"history 20 pagination");
  FuturesMonitorScreen[] page=new FuturesMonitorScreen[1];String[] token={""};int[] starts={0},stops={0};f.ui(()->{try{page[0]=new FuturesMonitorScreen(f.activity,file,(t,s)->{token[0]=t;starts[0]++;check(s.equals(Collections.singletonList("IF0")),"only selected request");},t->stops[0]++);check(starts[0]==0,"open no fetch");page[0].refresh.performClick();page[0].cancel();page[0].deliver(token[0],new JSONArray().put(new JSONObject().put("symbol","IF0").put("payload",PAYLOAD).put("receivedAt",NOW).put("sourceUrl",FuturesMonitorModel.sourceUrl("IF0"))),"");}catch(Exception e){throw new RuntimeException(e);}});
  f.ui(()->{try{check(stops[0]==1&&store.history("IF0",0,20).length()==1,"cancelled response ignored");page[0].openSnapshot(record.getString("id"));check(page[0].points.getChildCount()==2,"actual point buttons");page[0].openReader(0);FuturesMonitorScreen copy=new FuturesMonitorScreen(f.activity,file,(t,s)->starts[0]++,t->stops[0]++);copy.restoreState(page[0].saveState());check(copy.view==2&&copy.readerIndex==0&&copy.reader.getText().toString().contains("audit"),"reader recreation");copy.setDarkTheme(true);check(copy.back()&&copy.back()&&!copy.back(),"internal back");check(starts[0]==1,"restore no fetch");copy.close();page[0].close();}catch(Exception e){throw new RuntimeException(e);}});
 }
}

